import { assertLiveSession } from '@/lib/auth/live-session';

/**
 * The defect `no-floating-promises` exists to catch: the admission check runs,
 * its promise is discarded, and the handler continues as though it passed.
 */
export function guard(sessionId: string, userId: string): string {
  assertLiveSession(sessionId, userId);
  return 'allowed';
}
